static PyObject*
_round_corner_apply(PyObject *self, PyObject *args)
{
    PyObject *buffer;

    int aa_enabled, a_radius, b_radius, width, height;

    unsigned char r, g, b;
    unsigned char transparent = 0;
    char *image_mode_str;

    if (!PyArg_ParseTuple(args, "isiibbbiiO|b:apply", &aa_enabled, &image_mode_str, &a_radius, &b_radius, &r, &g, &b,
            &width, &height, &buffer, &transparent)) {
        return NULL;
    }

    unsigned char *ptr = (unsigned char *) PyBytes_AsString(buffer);

    int num_bytes = bytes_per_pixel(image_mode_str);

    int r_idx = rgb_order(image_mode_str, 'R'),
        g_idx = rgb_order(image_mode_str, 'G'),
        b_idx = rgb_order(image_mode_str, 'B'),
        a_idx = rgb_order(image_mode_str, 'A');

    float aa_amount = .75f;

    if (a_radius > width / 2) {
        a_radius = width / 2;
    }
    if (b_radius > height / 2) {
        b_radius = height / 2;
    }

    float a_rad = (float)a_radius, b_rad = (float)b_radius;
    float x;
    int y = 0;

